import React from "react";
import * as Icons from "react-icons";

interface IconButtonProps {
  name: keyof typeof Icons; 
  size?: number;
  color?: string;
  onClick?: () => void;
  className?: string;
}

const IconButton: React.FC<IconButtonProps> = ({
  name,
  size = 24,
  color = "white",
  onClick,
  className = "",
}) => {
  const IconComponent = Icons[name];

  if (!IconComponent) {
    return <div>Icon not found</div>;
  }

  return (
    <button
      onClick={onClick}
      className={`flex items-center justify-center gap-2 w-9 h-9   bg-[#2A2A36] hover:bg-blue-700 text-white rounded-full shadow-md transition-all ${className}`}
    >
      <IconComponent size={size} color={color} />
    </button>
  );
};

export default IconButton;

